-- Hand-maintained. Reflects edgar_warehouse.silver_store._DDL's sec_ownership_derivative_txn table.
-- Originally generated by infra/scripts/generate_silver_dbt_models.py, deleted by
-- DuckDB Retirement Cutover Ticket 07 -- there is no regeneration step anymore;
-- edit this file directly when silver_store.py's schema changes.

{{ silver_model_config('SEC_OWNERSHIP_DERIVATIVE_TXN') }}

-- Ticket 06: materializes the issuer's cik here, via a join to
-- sec_company_filing, so downstream consumers (gold, MDM) don't each have
-- to independently know this table needs an accession-number join to
-- resolve issuer CIK (sec_adv_filing.cik-is-NULL-for-ADV-data is the same
-- failure shape this is deliberately avoiding a repeat of).
with collapsed as (
select
    accession_number,
    owner_index,
    txn_index,
    security_title,
    transaction_date,
    transaction_code,
    transaction_shares,
    transaction_price,
    acquired_disposed_code,
    shares_owned_after,
    ownership_nature,
    ownership_direct_indirect,
    conversion_or_exercise_price,
    exercise_date,
    expiration_date,
    underlying_security_title,
    underlying_security_shares,
    parser_version,
    last_sync_run_id,
    mdm_entity_id
from {{ source('edgartools_silver_landing', 'SEC_OWNERSHIP_DERIVATIVE_TXN') }}
qualify row_number() over (
    partition by accession_number, owner_index, txn_index
    order by parse_sequence desc
) = 1
  and {{ silver_not_retired('sec_ownership_derivative_txn', "concat_ws('|', accession_number, owner_index, txn_index)") }}
)
select
    collapsed.*,
    company_filing.cik
from collapsed
left join {{ ref('sec_company_filing') }} as company_filing
    on company_filing.accession_number = collapsed.accession_number
